function esthetics(){const car=E.active(state);if(!appearanceDraft||appearanceDraftUid!==car.uid){appearanceDraft=K.current(car);appearanceDraftUid=car.uid;}const a=appearanceDraft,quote=E.cosmeticQuote(state,car,a),options=(key,list)=>list.map(([id,label])=>`<option value="${id}" ${a[key]===id?'selected':''}>${label}</option>`).join('');return title('DISTRITO COMERCIAL / PINTURA Y ESTÉTICA','Tu auto. Tu firma.','Probá colores y diseños sin costo. El trabajo se realiza y se cobra únicamente al confirmar.',button('← Mapa de tiendas','market-map','','secondary'))+(state.race?'<div class="notice">El local puede mostrar tu auto, pero los trabajos se realizan después de terminar y cobrar la carrera.</div>':'')+`<div class="esthetic-layout"><section class="panel"><div class="panel-head"><h2>${esc(C.car(car.id).name)} · vista previa</h2><small>EN EL TALLER</small></div><canvas id="customGarageCanvas" aria-label="Vista previa del auto personalizado en el taller"></canvas><div class="visual-foot"><small>Las piezas mecánicas montadas conservan su apariencia y rendimiento.</small></div></section><section class="panel cosmetic-form"><div class="panel-head"><h2>Elegí los trabajos</h2><small>AUTO #${car.number}</small></div><div class="custom-grid"><label>Pintura · ${money(E.cost(state,450))}<input type="color" id="visualPaint" value="${a.color}" ${disabled()}></label><label>Dorsal · ${money(E.cost(state,90))}<input type="number" min="0" max="99" id="visualNumber" value="${a.number}" ${disabled()}></label><label>Diseño de llantas · ${money(E.cost(state,240))}<select id="visualRim" ${disabled()}>${options('rim',[['auto','Según neumático'],['steel','Acero'],['five','Cinco radios'],['mesh','Multirradio']])}</select></label><label>Pintura de llantas · ${money(E.cost(state,120))}<input type="color" id="visualRimColor" value="${a.rimColor}" ${disabled()}></label><label>Vinilos · ${money(E.cost(state,180))}<select id="visualDecal" ${disabled()}>${options('decal',[['stripe','Franja + número'],['band','Banda + número'],['number','Sólo número'],['clean','Liso']])}</select></label><label>Acento · ${money(E.cost(state,90))}<input type="color" id="visualAccent" value="${a.accent}" ${disabled()}></label></div><div class="cosmetic-quote"><span class="eyebrow">PRESUPUESTO / SÓLO LOS CAMBIOS</span><div id="cosmeticItems">${quote.items.length?quote.items.map(item=>`<div><span>${item.label}</span><b>${money(item.price)}</b></div>`).join(''):'<p>Elegí un cambio para ver el presupuesto.</p>'}</div><div class="cosmetic-total"><span>Total</span><b id="cosmeticTotal">${money(quote.total)}</b></div><div class="cosmetic-after"><span>Efectivo después del trabajo</span><b id="cosmeticBalance">${money(state.cash-quote.total)}</b></div><p id="cosmeticError" role="status"></p><button id="applyCosmetics" class="btn orange full" data-action="appearance" ${disabled()} ${!quote.total||state.cash<quote.total?'disabled':''}>Aplicar y pagar · ${money(quote.total)}</button><button class="text-button" data-action="cancel-appearance">Descartar vista previa</button><small>Los cambios son estéticos. El presupuesto se registra en los movimientos de Dirección.</small></div></section></div>`;}
