function updateFinishPopup(){
 const r=state.race;let box=$('finishPopup');
 const ready=r&&(r.phase==='finished'&&r.finish||r.closing?.playerReady);
 if(!ready||view!=='carrera'){box?.remove();return;}
 const created=!box;
 if(created){box=document.createElement('section');box.id='finishPopup';box.className='finish-popup';box.setAttribute('role','dialog');box.setAttribute('aria-labelledby','finishTitle');document.body.append(box);}
 const order=E.standings(r),position=r.finish?.position||order.findIndex(e=>e.id==='player')+1,retired=order.find(e=>e.id==='player')?.status==='dnf',stamp=r.phase+'|'+position+'|'+order.map(e=>[e.id,e.status,e.laps].join(':')).join('|');
 if(box.dataset.stamp===stamp)return;
 box.dataset.stamp=stamp;const focus=box.contains(document.activeElement);
 box.innerHTML=`<header><div class="eyebrow">BANDERA A CUADROS</div><h2 id="finishTitle">${retired?'Clasificado':'Terminaste'} P${position}${retired?' · Retirado':''}</h2><p>${r.phase==='finished'?'Clasificación final':'Posición al cruzar la meta. Los demás completan su vuelta.'}</p></header><div class="finish-details"><ol>${order.map((e,i)=>`<li class="${e.id==='player'?'player':''}"><b>${i+1}</b><i style="background:${e.color}"></i><span>#${e.number} ${esc(e.name)}</span><strong>${e.laps} V</strong><small>${e.status==='dnf'?'RET':e.status==='finished'?'✓':'EN PISTA'}</small></li>`).join('')}</ol><p>Los autos que ya terminaron vuelven a su box.</p>${r.exhibition?`<p>Exhibición · ${r.targetLaps} ${r.targetLaps===1?'vuelta':'vueltas'} · ${esc(C.categories[r.tier].name)}</p>`:r.finish?`<p>Premio y patrocinio: <b>${money(r.finish.prize+r.finish.sponsor)}</b><br>Sueldos y combustible: ${money(r.finish.wages+r.finish.fuelCost)} · ${r.finish.points} puntos.</p>`:''}</div><footer>${button('Cerrar carrera →','collect','','orange')}</footer>`;
 if(created||focus)box.querySelector('button').focus({preventScroll:true});
}
function frame(now){const dt=Math.max(0,Math.min((now-lastFrame)/1000,.35));lastFrame=now;GalponStraightTestUI.update(dt,state,E,save);if(view!=='menu'&&state.setupJob&&!document.hidden){if(E.advanceSetup(state,dt)){setupOwner=null;save();render();toast('Reglajes instalados.');}else updateSetupWork();}if(view!=='menu'&&travelRunning&&state.journey.trip&&!document.hidden){const arrived=J.advance(state,dt*J.travelSpeed);if(arrived){travelRunning=false;save();navigate('sede');toast('Llegaste a '+arrived.name+'. Podés seguir viaje o entrar desde el mapa.');}}if(view!=='menu'&&running&&(state.race?.phase==='running'||state.race?.phase==='finished'&&state.race?.closing&&!state.race.closing.done)&&!document.hidden){accumulator+=dt;const steps=Math.floor(accumulator);if(steps){V.captureBefore(state);E.tick(state,steps);V.captureAfter(state,steps,speed);accumulator-=steps;if(state.race.phase==='finished'&&(!state.race.closing||state.race.closing.done)){running=false;save();if(view==='carrera')render();else{header();if(view==='sede')render();toast('Bandera a cuadros. El resultado está listo en Carrera.');}}}}
 if($('journeyCanvas')&&!document.hidden&&(travelRunning||JU.needsMapDraw($('journeyCanvas'),state)))JU.drawMap($('journeyCanvas'),state);if(now-lastUI>250){if(view==='carrera'&&state.race&&(lastUIRace!==state.race||lastUITick!==state.race.time||lastUIRunning!==running)){updateRace();lastUIRace=state.race;lastUITick=state.race.time;lastUIRunning=running;}updateFinishPopup();lastUI=now;}if(view==='carrera'&&running&&!document.hidden){if($('raceCanvas'))V.broadcastViews($('raceCanvas'),$('followCanvas'),state);drawTime=now;}if(now-lastSave>10000){save();lastSave=now;}GalponAudio.update(state,view,running,travelRunning,now);requestAnimationFrame(frame);}
